// Test-bench input for UpLead: {domain|website, job_function?, job_sub_function?,
// management_level?, title?, num_results?, count_only?}. Pure sandbox -- writes
// NOTHING to Firestore, not wired into workflows 25/26. Verified against real
// UpLead docs (docs.uplead.com) 2026-07-23 before building, same discipline as
// every other integration in this project (CoreClaw, PDL).
//
// WHY UPLEAD, AFTER PDL (added 2026-07-23): PDL's contact fields (work_email,
// mobile_phone, phone_numbers) came back masked as a literal boolean `true`
// even on the paid Person Enrichment endpoint, despite those being documented
// Base-schema fields -- a dead end that neither PDL's public docs nor field-
// bundle docs explain. Justin's call: abandon PDL for CONTACT enrichment (it
// may still be fine for general people/company background info, just not for
// getting a reachable email/phone). UpLead's Prospector API returns FULLY
// UNMASKED contact data directly in the search response (real `email`,
// `email_status`, `phone_number`, `mobile_directdial`) -- no separate paid
// reveal step like PDL needed. It also has a `job_function` filter (with
// "human resources" as its own distinct value from "operations"/
// "manufacturing") that PDL's seniority-only `job_title_levels` couldn't
// offer -- directly solving the "don't want to end up contacting HR" problem
// Justin hit with PDL's Coastal Pacific test (which returned an HR Manager
// alongside two better-fit candidates).
//
// NO FREE PREVIEW ON A NORMAL ACCOUNT: UpLead's docs DO describe a masked
// preview endpoint (`/v2/prospector-preview`, returns just name/title/company,
// no contact info) but its own docs say "Only for resellers" -- not available
// on a normal self-serve account. So unlike PDL's search-then-reveal design,
// there is no zero-cost way to browse candidates before they're pulled and
// billed. Justin's explicit call: fine, as long as the data quality is good --
// just keep num_results capped low so cost stays predictable (his words:
// "keep that cap low").
//
// COST CONTROL: `num_results` is hard-capped at MAX_RESULTS regardless of what
// the caller requests (UpLead bills per contact RETURNED, same as PDL's
// Person Search billing model -- see docs.uplead.com "Prospector API").
// Defaults to DEFAULT_RESULTS if not specified. A `count_only:true` flag runs
// the free/uncosted count-only mode instead (UpLead's own `count_only` param)
// so total match volume can be checked before deciding how many to actually
// pull.
const MAX_RESULTS = 5;
const DEFAULT_RESULTS = 2;
const b = $json.body || $json || {};
let website = (b.domain || b.website || '').trim();
// Same protocol/www/path stripping this project already uses for CoreClaw and
// PDL website fields (see openNPModal in index.html).
let domain = website.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].trim();
if (!domain) {
  throw new Error('Test input needs a domain (or website) to search on.');
}
let numResults = parseInt(b.num_results, 10);
if (!Number.isFinite(numResults) || numResults < 1) numResults = DEFAULT_RESULTS;
if (numResults > MAX_RESULTS) numResults = MAX_RESULTS;
return [{ json: {
  domain,
  job_function: (b.job_function || '').trim(),
  job_sub_function: (b.job_sub_function || '').trim(),
  management_level: (b.management_level || '').trim(),
  title: (b.title || '').trim(),
  num_results: numResults,
  count_only: !!b.count_only
} }];

// Builds the query string by hand (rather than n8n's query-parameters UI)
// so optional/blank fields are cleanly omitted instead of being sent as
// empty-string params, which UpLead's API may reject or mis-handle. Every
// field here is a real, docs-confirmed Prospector API parameter (see
// docs.uplead.com "Prospector API" -> Parameters table): domain (required),
// job_function, job_sub_function, management_level, title (all optional
// string filters), per_page (bounded 1-100, we cap far lower for cost
// control), page, count_only.
const ctx = $json;
const parts = [];
function add(key, val) {
  if (val === undefined || val === null || val === '') return;
  parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(val));
}
add('domain', ctx.domain);
add('job_function', ctx.job_function);
add('job_sub_function', ctx.job_sub_function);
add('management_level', ctx.management_level);
add('title', ctx.title);
if (ctx.count_only) {
  add('count_only', 'true');
} else {
  add('per_page', ctx.num_results);
  add('page', 1);
}
return [{ json: { ...ctx, qs: parts.join('&') } }];

// Shapes a compact, side-by-side-comparable test result -- same purpose as
// wf27's "Build test response" for PDL, adapted for UpLead's response shape
// (docs.uplead.com "Prospector API" -> example response). Nothing written to
// Firestore. UpLead's contacts come back FULLY UNMASKED already (real email/
// phone strings, not booleans), so unlike wf27 there's no separate reveal
// step or `id`-for-later-reveal field needed here -- what you see in this
// response IS the real, usable contact.
const ctx = $('Build UpLead query').first().json;
const resp = $json || {};
const hadData = !!(resp && resp.data);
if (!hadData) {
  return [{ json: {
    provider: 'uplead',
    error: true,
    raw: resp,
    note: 'UpLead API call did not return the expected {data:...} shape -- likely a 400 (bad params)/401 (bad API key)/403 (no active subscription)/429 (rate limited). See "raw" for the actual response.'
  } }];
}
const rows = (resp.data && Array.isArray(resp.data.results)) ? resp.data.results : [];
const meta = (resp.data && resp.data.meta) ? resp.data.meta : {};
const countOnlyResult = (resp.data && typeof resp.data.count === 'number') ? resp.data.count : null;
const credits = (resp.userInfo && typeof resp.userInfo.availableCredits === 'number') ? resp.userInfo.availableCredits : null;
const candidates = rows.map(r => ({
  id: r.id || null,
  full_name: [r.first_name, r.last_name].filter(Boolean).join(' ') || null,
  title: r.title || null,
  job_function: r.job_function || null,
  job_sub_function: r.job_sub_function || null,
  management_level: r.management_level || null,
  email: r.email || null,
  email_status: r.email_status || null,
  has_valid_email: r.email_status === 'valid',
  phone_number: r.phone_number || null,
  mobile_directdial: r.mobile_directdial || null,
  linkedin_url: r.linkedin_url || null,
  company_name: r.company_name || null,
  industry: r.industry || null
}));
return [{ json: {
  provider: 'uplead',
  tested_business: { domain: ctx.domain, job_function: ctx.job_function, job_sub_function: ctx.job_sub_function, management_level: ctx.management_level, title: ctx.title },
  count_only_result: countOnlyResult,
  total_matches: (typeof meta.total === 'number') ? meta.total : null,
  candidates_returned: candidates.length,
  available_credits: credits,
  candidates,
  note: ctx.count_only
    ? 'count_only run -- no contacts were pulled or billed, this just reports total_matches (see count_only_result).'
    : (candidates.length === 0 ? 'No contacts matched this domain/job_function/management_level combination -- try loosening job_function or dropping management_level.' : undefined)
} }];
